import{_ as d,c as r,o as e,aj as a}from"./chunks/framework.B5VMNd4r.js";const c=JSON.parse('{"title":"第3章 AI写作与内容生成——开源写作助手盘点","description":"","frontmatter":{},"headers":[],"relativePath":"handbook/ai-tools/chapter_3.md","filePath":"handbook/ai-tools/chapter_3.md","lastUpdated":1783615807000}'),n={name:"handbook/ai-tools/chapter_3.md"};function h(o,t,l,p,b,s){return e(),r("div",null,[...t[0]||(t[0]=[a(`<h1 id="第3章-ai写作与内容生成——开源写作助手盘点" tabindex="-1">第3章 AI写作与内容生成——开源写作助手盘点 <a class="header-anchor" href="#第3章-ai写作与内容生成——开源写作助手盘点" aria-label="Permalink to “第3章 AI写作与内容生成——开源写作助手盘点”">​</a></h1><p>不用翻墙，不用付费，5个开源工具搭建你的私有AI写作助手。</p><p>我是怕浪猫，AI提效工具系列第3章。上两章聊了图片和视频，这章讲文字。</p><h2 id="_3-1-ollama-openwebui-本地大模型对话平台" tabindex="-1">3.1 Ollama+OpenWebUI：本地大模型对话平台 <a class="header-anchor" href="#_3-1-ollama-openwebui-本地大模型对话平台" aria-label="Permalink to “3.1 Ollama+OpenWebUI：本地大模型对话平台”">​</a></h2><p><strong>Ollama：本地运行大模型的极简方案</strong></p><p>Ollama把复杂的大模型部署简化到一行命令。</p><table tabindex="0"><thead><tr><th>特性</th><th>说明</th></tr></thead><tbody><tr><td>安装方式</td><td>一键安装（Mac/Windows/Linux）</td></tr><tr><td>模型管理</td><td>ollama pull/ollama run</td></tr><tr><td>模型格式</td><td>GGUF量化格式</td></tr><tr><td>API兼容</td><td>OpenAI兼容API</td></tr><tr><td>模型库</td><td>Llama、Qwen、DeepSeek、Mistral等</td></tr></tbody></table><p><strong>常用模型推荐</strong></p><table tabindex="0"><thead><tr><th>模型</th><th>参数量</th><th>显存需求</th><th>写作能力</th><th>中文能力</th></tr></thead><tbody><tr><td>Qwen2.5-7B</td><td>7B</td><td>6GB</td><td>好</td><td>优秀</td></tr><tr><td>DeepSeek-R1-7B</td><td>7B</td><td>6GB</td><td>好</td><td>优秀</td></tr><tr><td>Llama3.1-8B</td><td>8B</td><td>7GB</td><td>优秀</td><td>中</td></tr><tr><td>Qwen2.5-14B</td><td>14B</td><td>10GB</td><td>很好</td><td>优秀</td></tr><tr><td>DeepSeek-R1-14B</td><td>14B</td><td>10GB</td><td>很好</td><td>优秀</td></tr><tr><td>Mistral-7B</td><td>7B</td><td>6GB</td><td>好</td><td>弱</td></tr></tbody></table><blockquote><p>中文写作首选Qwen和DeepSeek。7B模型在4-bit量化下只需6GB显存，集显笔记本也能跑。</p></blockquote><p><strong>OpenWebUI：给Ollama套上ChatGPT界面</strong></p><table tabindex="0"><thead><tr><th>功能</th><th>说明</th></tr></thead><tbody><tr><td>多模型切换</td><td>下拉选择不同模型</td></tr><tr><td>对话管理</td><td>多会话、历史记录</td></tr><tr><td>文档对话</td><td>上传PDF/Word直接提问</td></tr><tr><td>联网搜索</td><td>集成搜索增强回答</td></tr><tr><td>提示词库</td><td>保存常用提示词模板</td></tr><tr><td>多用户</td><td>支持团队使用</td></tr><tr><td>RAG</td><td>内置检索增强生成</td></tr></tbody></table><p><strong>3步部署</strong></p><table tabindex="0"><thead><tr><th>步骤</th><th>命令/操作</th><th>说明</th></tr></thead><tbody><tr><td>1. 装Ollama</td><td>ollama pull qwen2.5:7b</td><td>下载模型</td></tr><tr><td>2. 装OpenWebUI</td><td>docker run -d -p 3000:8080 ...</td><td>Docker一行启动</td></tr><tr><td>3. 访问</td><td><a href="http://localhost:3000" target="_blank" rel="noreferrer">http://localhost:3000</a></td><td>浏览器使用</td></tr></tbody></table><h2 id="_3-2-anythingllm-文档对话与知识管理一体化" tabindex="-1">3.2 AnythingLLM：文档对话与知识管理一体化 <a class="header-anchor" href="#_3-2-anythingllm-文档对话与知识管理一体化" aria-label="Permalink to “3.2 AnythingLLM：文档对话与知识管理一体化”">​</a></h2><p>AnythingLLM把&quot;上传文档→AI问答&quot;这个过程做到了极致。</p><p><strong>核心能力</strong></p><table tabindex="0"><thead><tr><th>功能</th><th>说明</th></tr></thead><tbody><tr><td>文档对话</td><td>PDF/Word/Excel/PPT直接提问</td></tr><tr><td>多模型支持</td><td>OpenAI/Claude/Ollama/LocalAI</td></tr><tr><td>工作空间</td><td>按项目分类管理文档</td></tr><tr><td>Agent能力</td><td>可执行网页搜索、文档操作</td></tr><tr><td>向量数据库</td><td>内置LanceDB，无需额外配置</td></tr><tr><td>桌面版</td><td>Mac/Windows/Linux客户端</td></tr></tbody></table><p><strong>AnythingLLM vs OpenWebUI文档对话</strong></p><table tabindex="0"><thead><tr><th>维度</th><th>AnythingLLM</th><th>OpenWebUI</th></tr></thead><tbody><tr><td>定位</td><td>文档知识管理</td><td>通用对话平台</td></tr><tr><td>文档解析</td><td>强（复杂表格/图表）</td><td>中</td></tr><tr><td>多文档</td><td>工作空间分类管理</td><td>简单列表</td></tr><tr><td>Agent</td><td>支持</td><td>不支持</td></tr><tr><td>部署</td><td>桌面版/Docker</td><td>Docker</td></tr><tr><td>适合</td><td>企业知识库</td><td>个人对话</td></tr></tbody></table><blockquote><p>如果你主要需求是&quot;跟文档对话&quot;，AnythingLLM体验更好。如果还需要通用聊天、提示词管理等，OpenWebUI更全面。</p></blockquote><h2 id="_3-3-librechat-多模型对话与多端同步" tabindex="-1">3.3 LibreChat：多模型对话与多端同步 <a class="header-anchor" href="#_3-3-librechat-多模型对话与多端同步" aria-label="Permalink to “3.3 LibreChat：多模型对话与多端同步”">​</a></h2><p>LibreChat是另一个开源的ChatGPT替代品，最大亮点是多端同步。</p><p><strong>核心特性</strong></p><table tabindex="0"><thead><tr><th>功能</th><th>说明</th></tr></thead><tbody><tr><td>多模型</td><td>OpenAI/Claude/Gemini/Ollama/本地模型</td></tr><tr><td>多端同步</td><td>同一账号跨设备同步对话</td></tr><tr><td>Artifacts</td><td>类似Claude的Artifacts功能</td></tr><tr><td>插件系统</td><td>搜索、代码执行、图片生成</td></tr><tr><td>对话分支</td><td>从任意消息分叉新对话</td></tr><tr><td>书签</td><td>保存重要对话片段</td></tr><tr><td>导入导出</td><td>对话数据可迁移</td></tr></tbody></table><p><strong>3款对话工具对比</strong></p><table tabindex="0"><thead><tr><th>维度</th><th>OpenWebUI</th><th>AnythingLLM</th><th>LibreChat</th></tr></thead><tbody><tr><td>定位</td><td>本地模型对话</td><td>文档知识管理</td><td>多模型对话</td></tr><tr><td>多端同步</td><td>否</td><td>桌面版</td><td>是</td></tr><tr><td>文档对话</td><td>基础</td><td>强</td><td>基础</td></tr><tr><td>插件</td><td>少</td><td>Agent</td><td>丰富</td></tr><tr><td>部署难度</td><td>低</td><td>低</td><td>中</td></tr><tr><td>适合</td><td>个人本地</td><td>企业知识库</td><td>团队协作</td></tr></tbody></table><blockquote><p>三个工具不是互斥的。怕浪猫自己同时用OpenWebUI做日常对话，AnythingLLM管文档，LibreChat做多模型对比。</p></blockquote><h2 id="_3-4-沉浸式翻译-开源ai翻译工具" tabindex="-1">3.4 沉浸式翻译：开源AI翻译工具 <a class="header-anchor" href="#_3-4-沉浸式翻译-开源ai翻译工具" aria-label="Permalink to “3.4 沉浸式翻译：开源AI翻译工具”">​</a></h2><p>沉浸式翻译（Immersive Translate）是2025年最火的开源翻译工具之一。</p><p><strong>核心功能</strong></p><table tabindex="0"><thead><tr><th>功能</th><th>说明</th></tr></thead><tbody><tr><td>网页翻译</td><td>浏览器实时双语翻译</td></tr><tr><td>PDF翻译</td><td>保持排版的PDF翻译</td></tr><tr><td>视频字幕</td><td>YouTube等平台实时字幕翻译</td></tr><tr><td>EPUB翻译</td><td>电子书双语阅读</td></tr><tr><td>多引擎</td><td>OpenAI/Claude/DeepL/Google/本地模型</td></tr><tr><td>自定义</td><td>可配置提示词和翻译风格</td></tr></tbody></table><p><strong>翻译引擎对比</strong></p><table tabindex="0"><thead><tr><th>引擎</th><th>质量</th><th>速度</th><th>成本</th><th>隐私</th></tr></thead><tbody><tr><td>OpenAI GPT-4o</td><td>优秀</td><td>中</td><td>按Token</td><td>云端</td></tr><tr><td>Claude</td><td>优秀</td><td>中</td><td>按Token</td><td>云端</td></tr><tr><td>DeepL</td><td>很好</td><td>快</td><td>按字符</td><td>云端</td></tr><tr><td>Google</td><td>好</td><td>快</td><td>免费</td><td>云端</td></tr><tr><td>本地Ollama</td><td>好</td><td>中</td><td>免费</td><td>本地</td></tr></tbody></table><blockquote><p>隐私敏感的文档用本地Ollama翻译，日常网页用Google或DeepL，重要文档用GPT-4o。沉浸式翻译支持按场景自动切换引擎。</p></blockquote><p><strong>安装方式</strong></p><table tabindex="0"><thead><tr><th>平台</th><th>安装方式</th></tr></thead><tbody><tr><td>Chrome</td><td>Chrome Web Store搜索安装</td></tr><tr><td>Firefox</td><td>Add-ons搜索安装</td></tr><tr><td>油猴脚本</td><td>Tampermonkey脚本安装</td></tr><tr><td>桌面版</td><td>下载客户端（Mac/Windows）</td></tr></tbody></table><h2 id="_3-5-实战-搭建私有ai写作助手" tabindex="-1">3.5 实战：搭建私有AI写作助手 <a class="header-anchor" href="#_3-5-实战-搭建私有ai写作助手" aria-label="Permalink to “3.5 实战：搭建私有AI写作助手”">​</a></h2><p>把前面4个工具串起来，搭建一个完整的AI写作工作流。</p><p><strong>架构设计</strong></p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>需求输入 → Ollama+OpenWebUI（创意生成）</span></span>
<span class="line"><span>    → AnythingLLM（素材检索+事实核查）</span></span>
<span class="line"><span>    → 沉浸式翻译（多语言版本）</span></span>
<span class="line"><span>    → 输出成品</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><strong>各环节工具与职责</strong></p><table tabindex="0"><thead><tr><th>环节</th><th>工具</th><th>职责</th></tr></thead><tbody><tr><td>创意生成</td><td>OpenWebUI + Qwen2.5</td><td>头脑风暴、大纲生成</td></tr><tr><td>初稿撰写</td><td>OpenWebUI + DeepSeek-R1</td><td>正文写作</td></tr><tr><td>素材检索</td><td>AnythingLLM</td><td>从知识库找支撑材料</td></tr><tr><td>事实核查</td><td>AnythingLLM + 文档</td><td>验证关键数据</td></tr><tr><td>多语言</td><td>沉浸式翻译</td><td>英文/日文版本</td></tr><tr><td>润色</td><td>OpenWebUI + 自定义提示词</td><td>风格优化</td></tr></tbody></table><p><strong>提示词模板示例</strong></p><table tabindex="0"><thead><tr><th>场景</th><th>提示词模板</th></tr></thead><tbody><tr><td>大纲生成</td><td>&quot;请为以下主题生成一个{N}部分的系列文章大纲，每部分包含3个要点：{主题}&quot;</td></tr><tr><td>初稿撰写</td><td>&quot;请根据以下大纲撰写正文，风格{风格}，字数约{字数}，目标读者是{读者}：{大纲}&quot;</td></tr><tr><td>风格润色</td><td>&quot;请将以下文字改写为{风格}风格，保持信息不变，增强可读性：{原文}&quot;</td></tr><tr><td>事实核查</td><td>&quot;请检查以下陈述是否准确，标注不确定的部分：{陈述}&quot;</td></tr></tbody></table><p><strong>效率提升数据</strong></p><table tabindex="0"><thead><tr><th>环节</th><th>传统方式</th><th>AI辅助</th><th>提升幅度</th></tr></thead><tbody><tr><td>大纲构思</td><td>30分钟</td><td>5分钟</td><td>83%</td></tr><tr><td>初稿撰写</td><td>3小时</td><td>40分钟</td><td>78%</td></tr><tr><td>素材查找</td><td>1小时</td><td>10分钟</td><td>83%</td></tr><tr><td>多语言翻译</td><td>2小时</td><td>15分钟</td><td>87%</td></tr><tr><td>润色修改</td><td>1小时</td><td>20分钟</td><td>67%</td></tr><tr><td>合计</td><td>7.5小时</td><td>1.5小时</td><td>80%</td></tr></tbody></table><blockquote><p>AI写作不是让AI替你写，而是让AI做80%的基础工作，你专注20%的创意和判断。</p></blockquote><hr><p>你日常写作最需要AI帮忙做什么？大纲、初稿还是润色？评论区说说。</p><p>收藏这章，5款开源写作工具的部署指南和对比表随时查阅。</p><p>关注怕浪猫，下期讲AI效率办公——用Dify、FastGPT、n8n搭建自动化工作流。</p><p>系列进度 3/8 — 下一篇：AI效率办公的开源方案</p>`,53)])])}const g=d(n,[["render",h]]);export{c as __pageData,g as default};
